BUS.addEventListener('message', async (e) => {
    const { type, payload, target, from, tabId } = e.data || {};
    if (tabId && tabId !== TAB_ID && type !== 'SEARCH_CACHE_CLEARED') return;
    if (target !== '*' && target !== ctxId) return;

    switch (type) {
        case 'REQUEST_CATALOG':
            if (window.lite_data) emitEvent('RENDER_CATALOG', window.lite_data, 'side');
            break;

        case "LOCAL_SEARCH_RESULT":
            await searchStackReady;
            if (searchEngine) searchEngine.handleLocalSearchResult(payload);
            break;

        case "LOCAL_SEARCH_SNIPPETS_RESULT":
            await searchStackReady;
            if (searchEngine) searchEngine.handleLocalSearchSnippets(payload);
            break;

        case "SEARCH_CACHE_CLEARED":
            await searchStackReady;
            if (searchEngine) searchEngine.searchResultCache.clearMemory();
            break;

        case "reload_bookmark": {
            store.bookmarkhtml_modifing = "1";
            const rawHash = store.bookmarkhtml_linksHash;
            let attempts = 0;
            try {
                while (store.bookmarkhtml_linksHash === rawHash && attempts < 30 && store.resource_type === "bookmark") {
                    if ('caches' in window) {
                        try {
                            const keys = await caches.keys();
                            for (const key of keys) {
                                if (key.startsWith('core-cache-')) {
                                    const cache = await caches.open(key);
                                    await cache.delete('/src/tpl/bookmark.html');
                                }
                            }
                        } catch (err) { console.warn("清理书签缓存失败", err); }
                    }
                    const ifr = document.getElementById(from);
                    if (ifr && ifr.contentWindow) ifr.contentWindow.location.reload();
                    attempts++;
                    await AsyncUtils.wait(1000);
                }
            } finally {
                store.bookmarkhtml_modifing = "0";
                if (store.online_flag !== "0" && 'caches' in window) {
                    try {
                        const keys = await caches.keys();
                        for (const key of keys) {
                            if (key.startsWith('core-cache-')) {
                                const cache = await caches.open(key);
                                await cache.add('/src/tpl/bookmark.html');
                            }
                        }
                    } catch (err) { console.warn("回填书签缓存失败", err); }
                }
            }
            break;
        }

        case "image":
            window.__TXT_SEARCH_BRIDGE__.unregister();
            store.resource_type = "image";
            iframes.content.src = "about:blank";
            setTimeout(async () => {
                const { renderLightboxFrame } = await import('./lightbox-logic.js');
                renderLightboxFrame(iframes.content, 'image', { imageUrl: '../' + store.image_path });
            }, 20);
            break;

        case "video":
            window.__TXT_SEARCH_BRIDGE__.unregister();
            store.resource_type = "video";
            iframes.content.src = "about:blank";
            setTimeout(async () => {
                const { renderLightboxFrame } = await import('./lightbox-logic.js');
                renderLightboxFrame(iframes.content, 'video', { videoUrl: '../' + store.video_path });
            }, 20);
            break;

        case "pdf":
            window.__TXT_SEARCH_BRIDGE__.unregister();
            await AsyncUtils.wait(50);
            $("#content").src = "src/tpl/pdf.html?file=../../" + store.pdf_path;
            $("#content").focus();
            break;

        case "epub":
            window.__TXT_SEARCH_BRIDGE__.unregister();
            await AsyncUtils.wait(50);
            $("#content").src = "src/tpl/epub.html?book=../../" + store.epub_path;
            $("#content").focus();
            break;

        case "txt":
            await AsyncUtils.wait(50);
            $("#content").src = "src/tpl/txt.html?file=../../" + store.txt_path;
            $("#content").focus();
            break;

        case "audio": {
            await AsyncUtils.wait(50);
            const parts = store.song_path.split("/");
            const song = parts[parts.length - 1];
            const dir = store.song_path.split(song)[0];
            const m = await import('./audio-player.js');
            m.openAudioPlayer(song, dir, getAudioCtx());
            break;
        }

        case "play_fav_list": {
            const m = await import('./audio-player.js');
            m.playFavList(getAudioCtx());
            break;
        }

        case "PLAY_PRESET_AUDIO": {
            const m = await import('./audio-player.js');
            m.playPresetAudio(payload, getAudioCtx());
            break;
        }

        case "mask":
            payload.op == "add" ? $("#content").classList.add("mask") : $("#content").classList.remove("mask");
            break;

        case "adj_side_width":
            adj_side_width(payload.op);
            break;

        case "lightbox": {
            setLightboxState(payload && payload.status == "1");
            break;
        }

        case "quick_search": {
            const searchEl = $("#search");
            if (searchEl && searchEl.classList.contains("hide")) {
                searchEl.classList.remove("hide");
                searchEl.dataset.fsTemp = "1";
            }
            $("#searchInput").focus();
            break;
        }

        case "CLEAR_SEARCH": {
            const clearBtn = $("#clear");
            if (clearBtn) clearBtn.click();
            break;
        }

        case "load_comments": {
            const cm = await getCommentsModule();
            cm.loadComments(payload);
            break;
        }

        case "sh_comments": {
            const cm = await getCommentsModule();
            cm.toggleCommentsPopup(payload);
            break;
        }

        case "show_changelog":
            import('./deferred-features.js').then(m => m.showChangelog({ dbProxy, emitEvent }));
            break;

        case "OPEN_EXCERPTS_NOTEBOOK":
            import('./excerpts.js').then(m => m.ExcerptsUIManager.openAndRefresh());
            break;

        case "OPEN_MD_VIEWER":
            import('./deferred-features.js').then(m => m.openMdViewer(payload || {}));
            break;

        case "SAVE_EXCERPT": {
            const excerptText = typeof payload === 'string' ? payload : (payload && payload.text);
            if (!excerptText) break;
            let bookName = (payload && typeof payload === 'object' && payload.bookName) || "";
            if (!bookName) {
                bookName = "html";
                if (store.resource_type === 'txt' && store.txt_path) bookName = store.txt_path.split('/').pop();
                else if (store.resource_type === 'pdf' && store.pdf_path) bookName = store.pdf_path.split('/').pop();
                else if (store.resource_type === 'epub' && store.epub_path) bookName = store.epub_path.split('/').pop();
            }

            import('./excerpts.js').then(({ ExcerptsSys, ExcerptsUIManager }) => {
                ExcerptsSys.save(bookName, excerptText).then(() => {
                    if (document.getElementById('excerpts-popup') && document.getElementById('excerpts-popup').style.display !== 'none') {
                        ExcerptsUIManager.openAndRefresh();
                    }
                }).catch(e => console.error("摘抄失败", e));
            });
            break;
        }

        case 'SHOW_GLOBAL_BOOKMARKS':
            import('./deferred-features.js').then(m => m.showGlobalBookmarkMenu(payload.x, payload.y, payload.source));
            break;

        case 'CLOSE_GLOBAL_BOOKMARKS':
            if (window._closeGlobalMenu) window._closeGlobalMenu();
            break;

        default:
            break;
    }
});

